var PRESETS={ balanced:{carb:50,protein:20,fat:30}, keto:{carb:5,protein:20,fat:75},
  high:{carb:40,protein:30,fat:30}, lowcarb:{carb:25,protein:35,fat:40} };
function macro(cal, preset){
  var p=PRESETS[preset]||PRESETS.balanced;
  return { carb: cal*p.carb/100/4, protein: cal*p.protein/100/4, fat: cal*p.fat/100/9, pct:p };
}
var EXPORTS={PRESETS:PRESETS, macro:macro};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MacroForgePure = EXPORTS; }
